        #[inline(always)]
        pub const fn set_KEY(&mut self, val: u8) {
            self.0 = (self.0 & !(0xff << 24usize)) | (((val as u32) & 0xff) << 24usize);
        }
        ///WDT18\[30\] (read): Reset pulse output driving type. 0 = open-drain; 1 = push-pull.
        #[must_use]
        #[inline(always)]
        pub const fn PUSH_PULL(&self) -> bool {
            let val = (self.0 >> 30usize) & 0x01;
            val != 0
        }
        ///WDT18\[30\] (read): Reset pulse output driving type. 0 = open-drain; 1 = push-pull.
        #[inline(always)]
        pub const fn set_PUSH_PULL(&mut self, val: bool) {
            self.0 = (self.0 & !(0x01 << 30usize)) | (((val as u32) & 0x01) << 30usize);
        }
        ///WDT18\[31\] (read): Reset pulse polarity. 0 = active low; 1 = active high.
        #[must_use]
        #[inline(always)]
        pub const fn ACTIVE_HIGH(&self) -> bool {
            let val = (self.0 >> 31usize) & 0x01;
            val != 0
        }
